referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  let cells = Array.from({ length: d.text.length }, () => null);
  for (const r of d.ranges) for (let i = r[0]; i < r[1]; i++) cells[i] = r[2];
  cells.splice(d.start, d.end - d.start, ...Array(d.replacement.length).fill(null));
  const ranges = [];
  for (let i = 0; i < cells.length; ) {
    let j = i + 1;
    while (j < cells.length && cells[j] === cells[i]) j++;
    if (cells[i] !== null) ranges.push([i, j, cells[i]]);
    i = j;
  }
  return { text: d.text.slice(0, d.start) + d.replacement + d.text.slice(d.end), ranges };
}

